(6922163, 1042290, 19825, '<td valign="top">To me, you have perfectly captured what Thanksgiving is all about. Family and friends and fellowship (with a little food). Nice job, Marko.</td>', 'To me, you have perfectly captured what Thanksgiving is all about. Family and friends and fellowship (with a little food). Nice job, Marko.', '2012-12-04 06:21:34.000000', NULL, 0),
(6922164, 1042689, 19825, '<td valign="top">Look at you -- jumping back into challenges with a couple of top tens right off the bat. Good to see you back in the game, Scott. Congrats on the fine finish.</td>', 'Look at you -- jumping back into challenges with a couple of top tens right off the bat. Good to see you back in the game, Scott. Congrats on the fine finish.', '2012-12-04 06:24:08.000000', NULL, 0),
(6922167, 1042194, 77196, '<td valign="top">So much to be thankful for. An image to be treasured for generations.</td>', 'So much to be thankful for. An image to be treasured for generations.', '2012-12-04 06:28:48.000000', NULL, 0),
(6922168, 1042673, 19825, '<td valign="top">Fabulous. I can feel the warmth, laughter, and lively discussion that I love when sharing a great meal with ones I love. Nice job.</td>', 'Fabulous. I can feel the warmth, laughter, and lively discussion that I love when sharing a great meal with ones I love. Nice job.', '2012-12-04 06:29:51.000000', NULL, 0),
